package solution

import "runtime/debug"

// Revision returns the git commit embedded by the Go toolchain, if present.
func Revision() string {
	info, ok := debug.ReadBuildInfo()
	if !ok {
		return "unknown" // not built as a module / info unavailable
	}
	for _, s := range info.Settings { // build settings include VCS info
		if s.Key == "vcs.revision" {
			return s.Value
		}
	}
	return "unknown" // built without VCS stamping (e.g. go test)
}

codeLab.testHarness:
package solution

import "testing"

func TestRevision(t *testing.T) {
	// Under `go test`, vcs.revision is typically absent, so we expect
	// the graceful fallback rather than a panic or an empty string.
	got := Revision()
	if got == "" {
		t.Fatalf("Revision() returned empty string; want a value or \"unknown\"")
	}
	t.Logf("revision = %q", got)
}
